import assert from "node:assert/strict";
import { createSheet, setCell } from "../src/sheet.mjs";
import { valueOf, computeAll, dependents } from "../src/recalc.mjs";

test("valueOf and computeAll", () => {
  assert.equal(valueOf(" 2.5 "), 2.5);
  assert.equal(valueOf("tRUE"), true);
  assert.equal(valueOf("'12"), "12");
  const s = createSheet();
  setCell(s, "A1", "1");
  setCell(s, "A2", "=A1+1");
  setCell(s, "A3", "=A2+");
  const v = computeAll(s);
  assert.deepEqual([...v], [["A1", 1], ["A2", 2], ["A3", "#ERROR!"]]);
});

test("cycles and a long chain", () => {
  const s = createSheet();
  setCell(s, "A1", "=A1");
  setCell(s, "B1", "=A1+1");
  setCell(s, "C1", "1");
  setCell(s, "C2", "=C1+1");
  for (let i = 3; i <= 10000; i++) setCell(s, `C${i}`, `=C${i - 1}+1`);
  const v = computeAll(s);
  assert.equal(v.get("A1"), "#CYCLE!");
  assert.equal(v.get("B1"), "#CYCLE!");
  assert.equal(v.get("C10000"), 10000);
});

test("dependents order", () => {
  const s = createSheet();
  setCell(s, "A1", "1");
  setCell(s, "B2", "=A1+1");
  setCell(s, "A2", "=A1+1");
  setCell(s, "C1", "=B2+A2");
  assert.deepEqual(dependents(s, "A1"), ["A2", "B2", "C1"]);
});
