import { parseAddr, toAddr } from "./addr.mjs";
export function parseFormula(text) {
  const parts = text.split("+").map((s) => s.trim());
  if (parts.some((p) => p === "")) throw new SyntaxError("bad");
  return parts.map((p) => (/^\d+(\.\d+)?$/.test(p) ? { num: Number(p) } : { ref: toAddr(parseAddr(p).col, parseAddr(p).row) }));
}
export function refsOf(ast) { return ast.filter((t) => t.ref).map((t) => t.ref); }
export function evaluate(ast, lookup) {
  let s = 0;
  for (const t of ast) {
    const v = t.num ?? lookup(t.ref) ?? 0;
    if (typeof v !== "number") return typeof v === "string" && v.startsWith("#") ? v : "#VALUE!";
    s += v;
  }
  return s;
}
